    {
      "user": "No, just leaves. I will try again tomorrow.",
      "assistant": "That is okay. Come sit in my warm cave now."
    }
  ]
}

{
  "turns": [
    {
      "user": "I am thinking about spending my day in the garden.",
      "assistant": "That sounds nice! Do you like planting flowers or watering plants?"
    },
